import { expect, Locator, Page } from '@playwright/test';
import { BasePage } from './BasePage';
import { EnvUtils } from '../utils/envUtils';

export class LoginPage extends BasePage {
  public usernameInput: Locator;
  public passwordInput: Locator;
  public loginButton: Locator;

  constructor(page: Page) {
    super(page);
    this.usernameInput = page.getByRole('textbox', { name: /username|email/i });
    this.passwordInput = page.getByRole('textbox', { name: /password/i });
    this.loginButton = page.getByRole('button', { name: /login|sign in|submit/i });
  }

  public async navigateToLogin(): Promise<void> {
    await this.navigate(EnvUtils.BASE_URL);
  }

  public async login(username: string = EnvUtils.USERNAME, password: string = EnvUtils.PASSWORD): Promise<void> {
    await this.usernameInput.fill(username);
    await this.passwordInput.fill(password);
    await this.loginButton.click();
  }
}
```

#### `tests/auth.setup.ts`
```typescript
import { test as setup, expect } from '@playwright/test';
import { LoginPage } from '../pages/LoginPage';
import { EnvUtils } from '../utils/envUtils';
import * as path from 'path';
import * as fs from 'fs';

const authFile = path.join(__dirname, '../playwright/.auth/user.json');

setup('authenticate', async ({ page }) => {
  const loginPage = new LoginPage(page);
  await loginPage.navigateToLogin();

  // If login form is present, execute login flow
  if (await loginPage.usernameInput.isVisible({ timeout: 5000 }).catch(() => false)) {
    await loginPage.login(EnvUtils.USERNAME, EnvUtils.PASSWORD);
    await expect(page).not.toHaveURL(/.*login.*/i, { timeout: 15000 });
  }

  const authDir = path.dirname(authFile);
  if (!fs.existsSync(authDir)) {
    fs.mkdirSync(authDir, { recursive: true });
  }

  await page.context().storageState({ path: authFile });
});
```

